function validate([grid, k]) {
  if (grid.length < 1 || grid.length > 1000) return 'grid needs 1 to 1000 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 1000 || grid.some(row => row.length !== n)) return 'Every row needs the same length, from 1 to 1000.';
  if (grid.some(row => row.some(v => v < 1 || v > 1000000000))) return 'Each cell is between 1 and 10^9.';
  if (k < 1 || k > 1000000000) return 'k is between 1 and 10^9.';
  return null;
}

