function countSubmatrices(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const width = new Array(rows).fill(0);
  let total = 0;

  for (let col = 0; col < cols; col++) {
    for (let row = 0; row < rows; row++) {
      const value = grid[row][col];
      if (value > k) {
        width[row] = 0;
      } else if (col > 0 && grid[row][col - 1] >= value) {
        width[row] += 1;
      } else {
        width[row] = 1;
      }
    }

    const stack = [];
    let sum = 0;
    for (let row = 0; row < rows; row++) {
      let count = 1;
      while (stack.length > 0 && stack[stack.length - 1][0] >= width[row]) {
        const [height, times] = stack.pop();
        sum -= height * times;
        count += times;
      }
      stack.push([width[row], count]);
      sum += width[row] * count;
      total += sum;
    }
  }
  return total;
}

