function countSubmatrices(grid, k) {
  const m = grid.length, n = grid[0].length;
  let count = 0;
  // Try every block of rows x1..x2 and columns y1..y2 and test each cell directly.
  for (let x1 = 0; x1 < m; x1++)
    for (let x2 = x1; x2 < m; x2++)
      for (let y1 = 0; y1 < n; y1++)
        for (let y2 = y1; y2 < n; y2++) {
          let ok = true;
          for (let x = x1; x <= x2 && ok; x++)
            for (let y = y1; y <= y2 && ok; y++) {
              if (grid[x][y] > k) ok = false;
              else if (y > y1 && grid[x][y - 1] < grid[x][y]) ok = false;
            }
          if (ok) count++;
        }
  return count;
}

