function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const m = large ? 60 + pick(41) : 1 + pick(5);
  const n = large ? 60 + pick(41) : 1 + pick(5);
  const top = large ? [10, 1000, 1000000000][pick(3)] : 2 + pick(6);
  const style = pick(4);
  const constant = 1 + pick(top);
  const grid = [];
  for (let r = 0; r < m; r++) {
    const row = [];
    let value = 1 + pick(top);
    for (let c = 0; c < n; c++) {
      // 0: random cells; 1: falling runs that sometimes restart; 2: one value everywhere; 3: flat plateaus with jumps.
      if (style === 0) value = 1 + pick(top);
      else if (style === 1) value = rand() < 0.2 ? 1 + pick(top) : Math.max(1, value - pick(1 + Math.floor(top / 8)));
      else if (style === 2) value = constant;
      else if (rand() < 0.15) value = 1 + pick(top);
      row.push(value);
    }
    grid.push(row);
  }
  const k = Math.min(1000000000, 1 + pick(top + 1));
  return [grid, k];
}
